package escuela.personal.controller;
import escuela.personal.dto.*;
import escuela.personal.service.*;
import escuela.admin.dto.ResultadoAutocompletado;
import escuela.admin.support.MensajeErrorFormulario;
import escuela.common.exception.ReglaNegocioException;
import lombok.RequiredArgsConstructor;
import jakarta.validation.Valid;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.util.*;
import java.io.IOException;

@Controller @RequiredArgsConstructor @RequestMapping("/admin/configuracion-nomina/{idEmpleado}/prestamos")
public class PrestamoEmpleadoController {
 private final PrestamoEmpleadoService service;
 private final EmpleadoService empleados;
 @GetMapping("/{id:\\d+}/abonos") String abonos(@PathVariable("idEmpleado")Long emp,@PathVariable Long id,@RequestParam(defaultValue="0")int paginaAbonos,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){base(emp,origen,filtro,m);m.addAttribute("prestamo",service.obtener(emp,id));m.addAttribute("abonos",service.abonos(emp,id,paginaAbonos));return "admin/prestamo-empleado-abonos";}
 private String ruta(Long emp){return "/admin/configuracion-nomina/"+emp+"/prestamos";}
 private void base(Long emp,FiltroConfiguracionNomina origen,FiltroPrestamoEmpleado filtro,Model m){var f=origen.normalizado(empleados.hoyLaboral(emp));m.addAttribute("filtro",f);m.addAttribute("prestFiltro",filtro.normalizado());m.addAttribute("empleado",empleados.obtener(emp));m.addAttribute("rutaPrestamos",ruta(emp));m.addAttribute("volverUrl",filtro.url(f,ruta(emp)));m.addAttribute("configuracionUrl",f.url("/admin/configuracion-nomina/"+emp));m.addAttribute("puedeEditar",empleados.permitido("CONDICION_SALARIAL_ADMINISTRAR"));m.addAttribute("puedeEntregar",service.puedeEntregar());m.addAttribute("entregaHabilitada",service.entregaHabilitada());}
 @GetMapping String listado(@PathVariable("idEmpleado")Long emp,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){m.addAttribute("resultado",service.listar(emp,filtro));base(emp,origen,filtro,m);return "admin/prestamos-empleado";}
 @GetMapping("/nuevo") String nuevo(@PathVariable("idEmpleado")Long emp,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){empleados.autorizarSalarios(true);service.listar(emp,filtro);base(emp,origen,filtro,m);m.addAttribute("form",new PrestamoEmpleadoForm());m.addAttribute("idPrestamo",null);return "admin/prestamo-empleado-form";}
 @GetMapping("/{id:\\d+}/editar") String editar(@PathVariable("idEmpleado")Long emp,@PathVariable Long id,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){empleados.autorizarSalarios(true);m.addAttribute("form",service.formulario(emp,id));base(emp,origen,filtro,m);m.addAttribute("idPrestamo",id);return "admin/prestamo-empleado-form";}
 @PostMapping({"","/{id:\\d+}"}) String guardar(@PathVariable("idEmpleado")Long emp,@PathVariable(required=false)Long id,@Valid @ModelAttribute("form")PrestamoEmpleadoForm f,BindingResult errores,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m,RedirectAttributes flash){empleados.autorizarSalarios(true);empleados.autorizar(emp,true,false);if(!errores.hasErrors())try{Long guardado=service.guardar(emp,id,f);flash.addFlashAttribute("mensaje","Préstamo guardado como borrador. No se entregó dinero ni se creó una deducción fija.");return "redirect:"+filtro.url(origen.normalizado(empleados.hoyLaboral(emp)),ruta(emp)+"/"+guardado);}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Revisa los datos. La captura permanece aquí; no se guardaron cambios.");base(emp,origen,filtro,m);m.addAttribute("idPrestamo",id);return "admin/prestamo-empleado-form";}
 @GetMapping("/{id:\\d+}") String detalle(@PathVariable("idEmpleado")Long emp,@PathVariable Long id,@RequestParam(defaultValue="0")int paginaHistoriaPrestamo,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){var p=service.obtener(emp,id);base(emp,origen,filtro,m);m.addAttribute("prestamo",p);m.addAttribute("entrega",service.entrega(emp,id));m.addAttribute("historial",service.historial(emp,id,paginaHistoriaPrestamo));if(!m.containsAttribute("entregarForm")){var f=new EntregarPrestamoForm();f.setVersion(p.version());m.addAttribute("entregarForm",f);}return "admin/prestamo-empleado-detalle";}
 @PostMapping("/{id:\\d+}/cancelar") String cancelar(@PathVariable("idEmpleado")Long emp,@PathVariable Long id,@RequestParam Long version,@RequestParam String motivo,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){try{service.cancelar(emp,id,version,motivo);m.addAttribute("mensaje","Borrador cancelado con historial. No se movió dinero.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));m.addAttribute("motivoCapturado",motivo);}return detalle(emp,id,0,origen,filtro,m);}
 @PostMapping("/{id:\\d+}/revisar-entrega") String revisar(@PathVariable("idEmpleado")Long emp,@PathVariable Long id,@Valid @ModelAttribute("entregarForm")EntregarPrestamoForm f,BindingResult errores,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){if(!errores.hasErrors())try{m.addAttribute("revisionEntrega",service.revisar(emp,id,f));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}if(errores.hasErrors())m.addAttribute("errorOperacion","Revisa cuenta, motivo, referencia y confirmación de entrega real.");m.addAttribute("activeTabPrestamo","gestion");return detalle(emp,id,0,origen,filtro,m);}
 @PostMapping("/{id:\\d+}/entregar") String entregar(@PathVariable("idEmpleado")Long emp,@PathVariable Long id,@Valid @ModelAttribute("entregarForm")EntregarPrestamoForm f,BindingResult errores,@RequestParam String sello,@ModelAttribute FiltroConfiguracionNomina origen,@ModelAttribute FiltroPrestamoEmpleado filtro,Model m){if(!errores.hasErrors())try{Long mov=service.entregar(emp,id,f,sello);m.addAttribute("mensaje","Entrega registrada una sola vez. Movimiento #"+mov+". El saldo del préstamo no se reduce al preparar nómina.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","La confirmación no es válida. Revisa la entrega nuevamente.");m.addAttribute("activeTabPrestamo","gestion");return detalle(emp,id,0,origen,filtro,m);}
 @GetMapping("/conceptos/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> conceptos(@PathVariable("idEmpleado")Long emp,@RequestParam(defaultValue="")String q){var r=service.conceptos(emp,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(r.stream().limit(10).toList(),r.size()>10));}
 @GetMapping("/concepto") @ResponseBody ResponseEntity<?> concepto(@PathVariable("idEmpleado")Long emp,@RequestParam Long conceptoId){try{return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.concepto(emp,conceptoId));}catch(ReglaNegocioException e){return ResponseEntity.badRequest().cacheControl(CacheControl.noStore()).body(Map.of("mensaje",e.getMessage()));}}
 @GetMapping("/cuentas/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> cuentas(@PathVariable("idEmpleado")Long emp,@RequestParam(defaultValue="")String q){var r=service.cuentas(emp,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(r.stream().limit(10).toList(),r.size()>10));}
 @GetMapping("/motivos/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> motivos(@PathVariable("idEmpleado")Long emp,@RequestParam(defaultValue="")String q){var r=service.motivos(emp,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(r.stream().limit(10).toList(),r.size()>10));}
 @GetMapping("/excel") void excel(@PathVariable("idEmpleado")Long emp,@ModelAttribute FiltroPrestamoEmpleado filtro,HttpServletResponse response)throws IOException{service.listar(emp,filtro);response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");response.setHeader("Content-Disposition","attachment; filename=prestamos-empleado.xlsx");response.setHeader("Cache-Control","no-store");try(var b=new org.apache.poi.xssf.streaming.SXSSFWorkbook(100)){try{var s=b.createSheet("Préstamos");String[] cab={"Folio","Concepto","Importe autorizado","Parcialidad mensual","Moneda","Primer descuento","Estado","Saldo entregado pendiente","Motivo"};var h=s.createRow(0);for(int n=0;n<cab.length;n++){h.createCell(n).setCellValue(cab[n]);s.setColumnWidth(n,28*256);}var estilo=b.createCellStyle();estilo.setDataFormat(b.createDataFormat().getFormat("\"$\"#,##0.00"));int row=1,pag=0;boolean mas;do{var page=service.listar(emp,filtro.pagina(pag++));mas=page.hasNext();for(var p:page){Object[] datos={p.folio(),p.concepto(),p.importe(),p.parcialidad(),p.moneda(),p.primerDescuento().format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy")),p.estado(),p.saldo(),p.motivo()};var r=s.createRow(row++);for(int n=0;n<datos.length;n++){var c=r.createCell(n);if(datos[n] instanceof Number num){c.setCellValue(num.doubleValue());c.setCellStyle(estilo);}else c.setCellValue(Objects.toString(datos[n],""));}}}while(mas);s.createFreezePane(0,1);b.write(response.getOutputStream());}finally{b.dispose();}}}
}
